inline fun <T> measureAndLog(label: String, block: () -> T): T {
    val start = System.currentTimeMillis()
    val result = block()
    Log.d("Perf", "$label took ${System.currentTimeMillis() - start}ms")
    return result
}

fun loadUsers() = measureAndLog("loadUsers") {
    return@loadUsers repository.fetchUsers() // non-local return works here
}

inline fun runOnUiThread(
    crossinline action: () -> Unit  // used inside another lambda below
) {
    handler.post { action() } // non-local return here would be unsafe
}

inline fun retryOperation(
    times: Int,
    noinline onFailure: (Exception) -> Unit // stored, not inlined
): List<(Exception) -> Unit> {
    return List(times) { onFailure } // needs a real function reference
}
